class Solution {
  public int minZeroArray(int[] nums, int[][] queries) {
    if (!canZero(nums, queries, queries.length)) return -1;
    int lo = 0, hi = queries.length;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (canZero(nums, queries, mid)) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  // can the first k queries zero the array? (each index can absorb the sum of vals covering it)
  private boolean canZero(int[] nums, int[][] queries, int k) {
    int n = nums.length;
    long[] diff = new long[n + 1];
    for (int i = 0; i < k; i++) {
      diff[queries[i][0]] += queries[i][2];
      diff[queries[i][1] + 1] -= queries[i][2];
    }
    long cover = 0;
    for (int i = 0; i < n; i++) {
      cover += diff[i];
      if (cover < nums[i]) return false;
    }
    return true;
  }
}
